-- 0012_add_work_comment — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- comment: a note or update on a project, with @mentions (E5 AC2), shown in the feed with its source (AC4).
-- Staff see all rows; a client sees its own rows marked visibility = 'client'; partners see nothing until
-- a policy links rows to their assigned jobs. Restricted content (group F) never goes here: D-28 notes.
CREATE TABLE comment (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL,
  -- What the comment is about: the project today; case and visit links come with their tables.
  site_id     uuid,
  body        text NOT NULL CHECK (btrim(body) <> ''),
  -- OCS users @mentioned in the body; they get a notice (E5 AC2).
  mentions    uuid[] NOT NULL DEFAULT '{}',
  author_id   uuid NOT NULL,
  source_kind text NOT NULL DEFAULT 'manual' CHECK (source_kind IN
                ('manual', 'mail', 'dingtalk', 'meeting', 'visit', 'alert')),
  source_ref  text,
  visibility  text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  CONSTRAINT comment_linked CHECK (num_nonnulls(site_id) >= 1),
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX comment_site ON comment (site_id, created_at);
CREATE INDEX comment_client ON comment (client_id);
CREATE INDEX comment_mentions ON comment USING gin (mentions);

-- "Turn into action" (E5 AC2): the action keeps a typed link to the comment it came from.
ALTER TABLE action ADD COLUMN comment_id uuid REFERENCES comment (id);
ALTER TABLE action ADD CONSTRAINT action_comment_source
  CHECK (comment_id IS NULL OR source_kind = 'comment');

ALTER TABLE comment ENABLE ROW LEVEL SECURITY;
CREATE POLICY comment_internal ON comment FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY comment_client_read ON comment FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON comment TO ocs_app;
